import React, { useState } from 'react';
import { Tabs, TabsList, TabsTrigger, TabsContent } from './ui/tabs'; 
import { Trash2, Archive, Plus, Users, BookOpen, MapPin, Calendar, Play, X, Clock, RefreshCw } from 'lucide-react';
import axios from 'axios';

const DepartmentCard = ({ deptName = "Information Systems", deptCode = "IS", deptId = 1, onGenerate }) => {
  // --- 1. CORE CONFIGURATION STATE ---
  const [activeYear, setActiveYear] = useState("1");
  const [examDays, setExamDays] = useState(1);
  const [dates, setDates] = useState(['']);
  const [windowStart, setWindowStart] = useState("08:00");
  const [windowEnd, setWindowEnd] = useState("17:00");
  const [sectionCount, setSectionCount] = useState(1);

  // --- 2. PREFERENCE LOGIC STATE ---
  const [proctorPref, setProctorPref] = useState("department"); // "department" or "global"
  const [roomPref, setRoomPref] = useState("department"); // "department" or "global"

  // --- 3. ENTITY STATE (Full CRUD & Archive Support) ---
  const [subjects, setSubjects] = useState({ 1: [], 2: [], 3: [], 4: [], 5: [] });
  const [newSub, setNewSub] = useState({ code: '', name: '', duration: 60 });

  const [proctors, setProctors] = useState([]); 
  const [currentProctorName, setCurrentProctorName] = useState("");
  const [tempAvail, setTempAvail] = useState({ date: '', start: '', end: '' });

  const [localRooms, setLocalRooms] = useState([]);
  const [newRoom, setNewRoom] = useState("");

  // --- LOGIC: SUBJECTS (30-Subject Hard Limit) ---
  const addSubject = () => {
    if (subjects[activeYear].length >= 30) return alert("STRICT LIMIT: Maximum 30 subjects per year level.");
    if (!newSub.code || !newSub.name) return;

    const entry = { ...newSub, id: Date.now(), duration_mins: newSub.duration, status: 'active' };
    setSubjects({ ...subjects, [activeYear]: [...subjects[activeYear], entry] });
    setNewSub({ code: '', name: '', duration: 60 });
  };

  const toggleArchiveSubject = (id) => {
    setSubjects({
      ...subjects,
      [activeYear]: subjects[activeYear].map(s => s.id === id ? { ...s, status: s.status === 'active' ? 'archived' : 'active' } : s)
    });
  };

  // --- LOGIC: PROCTORS (Availability & Reactivation) ---
  const addProctor = () => {
    if (!currentProctorName) return;
    setProctors([...proctors, { id: Date.now(), name: currentProctorName, availability: [], assignedToday: false }]);
    setCurrentProctorName("");
  };

  const saveAvailability = (pId) => {
    if (!tempAvail.date || !tempAvail.start || !tempAvail.end) return alert("Define full availability window.");
    setProctors(proctors.map(p => p.id === pId ? { ...p, availability: [...p.availability, { ...tempAvail }] } : p));
    setTempAvail({ date: '', start: '', end: '' });
  };

  const reactivateProctor = (pId) => {
    setProctors(proctors.map(p => p.id === pId ? { ...p, assignedToday: false } : p));
  };

  // --- LOGIC: ROOMS ---
  const addRoom = () => {
    if (!newRoom) return;
    if (localRooms.some(r => r.number === newRoom)) return alert("Room already registered.");
    setLocalRooms([...localRooms, { id: Date.now(), number: newRoom, status: 'active' }]);
    setNewRoom("");
  };

  // --- GENERATOR TRIGGER (Strict Unified Logic) ---
  const generateSchedule = async () => {
    try {
        const payload = {
            deptId,
            examDates: dates.filter(d => d !== ''),
            timeWindow: { start: windowStart, end: windowEnd },
            sectionsPerYear: sectionCount,
            preferences: { proctor: proctorPref, room: roomPref },
            // Filter only active subjects for the engine
            subjects: subjects[activeYear].filter(s => s.status === 'active')
        };

        const res = await axios.post(`/api/generate`, payload);

        if (onGenerate) {
            onGenerate(res.data.schedule, payload.examDates);
        }
    } catch (err) {
        alert("Scheduling Aborted: Conflict detected or resource exhaustion.");
    }
  };

  const handleDayChange = (val) => {
    const num = Math.max(1, parseInt(val) || 0);
    setExamDays(num);
    setDates(new Array(num).fill(''));
  };

  return (
    <div className="max-w-4xl mx-auto bg-white rounded-2xl shadow-2xl border border-slate-200 overflow-hidden mb-12">

      {/* HEADER: Archive & Status */}
      <div className="bg-slate-900 p-5 text-white flex justify-between items-center">
        <div>
          <h2 className="text-xl font-black uppercase tracking-tighter">{deptName}</h2>
          <p className="text-[10px] text-slate-400 font-bold tracking-[0.2em]">DEPT CODE: {deptCode}</p>
        </div>
        <button className="text-slate-400 hover:text-white transition-colors flex items-center gap-2 text-xs font-bold">
          <Archive size={16} /> ARCHIVE DEPT
        </button>
      </div>

      <div className="p-8">
        <Tabs defaultValue="subjects" className="w-full">
          <TabsList className="grid w-full grid-cols-3 mb-10 bg-slate-100 p-1.5 rounded-xl border border-slate-200">
            <TabsTrigger value="subjects" className="font-bold py-3"><BookOpen size={16} className="mr-2"/> Subjects</TabsTrigger>
            <TabsTrigger value="proctors" className="font-bold py-3"><Users size={16} className="mr-2"/> Proctors</TabsTrigger>
            <TabsTrigger value="rooms" className="font-bold py-3"><MapPin size={16} className="mr-2"/> Rooms</TabsTrigger>
          </TabsList>

          {/* TAB A: SUBJECTS (30-Subject Grid) */}
          <TabsContent value="subjects" className="space-y-6">
            <div className="flex items-center gap-3 bg-blue-50/50 p-4 rounded-xl border border-blue-100">
              <select className="border-none bg-white shadow-sm p-2 rounded-lg font-black text-xs" value={activeYear} onChange={(e)=>setActiveYear(e.target.value)}>
                {[1,2,3,4,5].map(y => <option key={y} value={y}>YEAR {y}</option>)}
              </select>
              <input placeholder="Code" className="w-24 p-2 rounded-lg border-none shadow-sm uppercase text-xs font-bold" value={newSub.code} onChange={(e)=>setNewSub({...newSub, code: e.target.value})}/>
              <input placeholder="Subject Name" className="flex-1 p-2 rounded-lg border-none shadow-sm text-xs font-bold" value={newSub.name} onChange={(e)=>setNewSub({...newSub, name: e.target.value})}/>
              <div className="flex items-center gap-2 bg-white px-3 py-2 rounded-lg shadow-sm border border-blue-100">
                <Clock size={14} className="text-blue-500"/>
                <input type="number" className="w-10 text-xs font-black outline-none" value={newSub.duration} onChange={(e)=>setNewSub({...newSub, duration: parseInt(e.target.value)})}/>
                <span className="text-[10px] font-black text-slate-300 uppercase">Mins</span>
              </div>
              <button onClick={addSubject} className="bg-blue-600 text-white p-2.5 rounded-lg hover:bg-blue-700 shadow-lg shadow-blue-200"><Plus size={20}/></button>
            </div>

            <div className="grid grid-cols-2 gap-3 max-h-72 overflow-y-auto pr-2">
              {subjects[activeYear].map(sub => (
                <div key={sub.id} className={`flex justify-between items-center p-3 border rounded-xl transition-all ${sub.status === 'archived' ? 'opacity-40 bg-slate-100' : 'bg-white shadow-sm hover:shadow-md'}`}>
                  <div className="flex flex-col">
                    <span className="font-black text-[11px] text-blue-600 uppercase">{sub.code}</span>
                    <span className="text-xs font-bold text-slate-700 truncate max-w-[150px]">{sub.name}</span>
                  </div>
                  <div className="flex items-center gap-2">
                    <span className="text-[10px] font-black bg-slate-100 px-2 py-1 rounded tracking-tighter">{sub.duration_mins}m</span>
                    <button onClick={()=>toggleArchiveSubject(sub.id)} className="text-slate-300 hover:text-amber-500 transition-colors">
                        <Archive size={14}/>
                    </button>
                  </div>
                </div>
              ))}
            </div>
          </TabsContent>

          {/* TAB B: PROCTORS (Reactivation Logic) */}
          <TabsContent value="proctors" className="space-y-6">
            <div className="flex gap-3 p-4 bg-emerald-50 rounded-xl border border-emerald-100">
              <input placeholder="Proctor Full Name" className="flex-1 p-2 rounded-lg border-none shadow-sm text-xs font-bold" value={currentProctorName} onChange={(e)=>setCurrentProctorName(e.target.value)}/>
              <button onClick={addProctor} className="bg-emerald-600 text-white px-6 py-2 rounded-lg font-black text-xs flex items-center gap-2 shadow-lg shadow-emerald-200">
                <Plus size={16}/> ADD PROCTOR
              </button>
            </div>

            <div className="grid grid-cols-1 gap-4 max-h-[400px] overflow-y-auto">
              {proctors.map(p => (
                <div key={p.id} className="border border-slate-100 rounded-xl p-4 bg-white shadow-sm">
                  <div className="flex justify-between items-center mb-3">
                    <h4 className="font-black text-slate-800 text-sm flex items-center gap-2">
                        {p.name} {p.assignedToday && <span className="bg-rose-100 text-rose-600 px-2 py-0.5 rounded text-[9px] uppercase">Assigned</span>}
                    </h4>
                    {p.assignedToday && (
                        <button onClick={() => reactivateProctor(p.id)} className="flex items-center gap-1 text-[10px] font-black text-emerald-600 hover:underline">
                            <RefreshCw size={12}/> REACTIVATE
                        </button>
                    )}
                  </div>
                  <div className="flex flex-wrap gap-2 items-center bg-slate-50 p-2 rounded-lg">
                    <input type="date" className="text-[10px] p-1 border rounded font-bold" value={tempAvail.date} onChange={(e)=>setTempAvail({...tempAvail, date: e.target.value})}/>
                    <input type="time" className="text-[10px] p-1 border rounded font-bold" value={tempAvail.start} onChange={(e)=>setTempAvail({...tempAvail, start: e.target.value})}/>
                    <input type="time" className="text-[10px] p-1 border rounded font-bold" value={tempAvail.end} onChange={(e)=>setTempAvail({...tempAvail, end: e.target.value})}/>
                    <button onClick={()=>saveAvailability(p.id)} className="bg-slate-800 text-white px-3 py-1 rounded text-[10px] font-black ml-auto">ADD AVAILABILITY</button>
                  </div>
                </div>
              ))}
            </div>
          </TabsContent>

          {/* TAB C: ROOMS (Dept Preferred vs Global) */}
          <TabsContent value="rooms" className="space-y-6">
            <div className="bg-amber-50/50 p-4 rounded-xl border border-amber-100 flex gap-3">
                <input placeholder="Room Number (e.g. 305)" className="flex-1 p-2 rounded-lg border-none shadow-sm text-xs font-bold uppercase" value={newRoom} onChange={(e) => setNewRoom(e.target.value.toUpperCase())}/>
                <button onClick={addRoom} className="bg-amber-600 text-white px-6 py-2 rounded-lg font-black text-xs shadow-lg shadow-amber-200">REGISTER ROOM</button>
            </div>
            <div className="flex flex-wrap gap-2">
              {localRooms.map(room => (
                <div key={room.id} className="flex items-center gap-3 bg-white px-4 py-2 rounded-xl border border-slate-100 shadow-sm">
                  <span className="font-black text-xs text-slate-700">{room.number}</span>
                  <button onClick={() => setLocalRooms(localRooms.filter(r => r.id !== room.id))} className="text-slate-300 hover:text-rose-500">
                    <X size={14}/>
                  </button>
                </div>
              ))}
            </div>
          </TabsContent>
        </Tabs>

        {/* 4. UNIFIED GENERATOR CONFIGURATION */}
        <div className="mt-12 bg-slate-900 rounded-3xl p-8 text-white relative overflow-hidden shadow-2xl">
            <div className="absolute top-0 right-0 p-8 opacity-10"><Play size={120} fill="currentColor"/></div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-10 relative z-10">
              {/* Left Column: Timeline */}
              <div className="space-y-8">
                <div>
                  <label className="text-[10px] text-blue-400 font-black uppercase tracking-widest block mb-3">Exam Days Duration</label>
                  <input type="number" value={examDays} min="1" className="w-full bg-slate-800/50 border border-slate-700 p-4 rounded-2xl text-2xl font-black focus:ring-2 ring-blue-500 outline-none" onChange={(e)=>handleDayChange(e.target.value)}/>
                </div>
                <div className="space-y-3 max-h-48 overflow-y-auto pr-3">
                    {dates.map((d, i) => (
                        <div key={i} className="flex items-center gap-3">
                            <span className="text-[10px] font-black text-slate-500 w-8">DAY {i+1}</span>
                            <input type="date" className="flex-1 bg-slate-800/30 border border-slate-700 p-3 rounded-xl text-xs font-bold" value={d} onChange={(e)=>updateDate(i, e.target.value)}/>
                        </div>
                    ))}
                </div>
              </div>

              {/* Right Column: Preferences & Batching */}
              <div className="space-y-8">
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="text-[10px] text-slate-500 font-black uppercase block mb-2">Window Start</label>
                    <input type="time" value={windowStart} onChange={(e)=>setWindowStart(e.target.value)} className="w-full bg-slate-800/50 border border-slate-700 p-4 rounded-2xl text-sm font-black"/>
                  </div>
                  <div>
                    <label className="text-[10px] text-slate-500 font-black uppercase block mb-2">Window End</label>
                    <input type="time" value={windowEnd} onChange={(e)=>setWindowEnd(e.target.value)} className="w-full bg-slate-800/50 border border-slate-700 p-4 rounded-2xl text-sm font-black"/>
                  </div>
                </div>

                <div className="bg-slate-800/40 p-5 rounded-2xl border border-slate-700 space-y-4">
                   <div className="flex justify-between items-center">
                        <label className="text-[10px] font-black uppercase text-slate-400">Total Sections</label>
                        <input type="number" min="1" className="bg-slate-900 w-16 p-2 rounded text-center font-black" value={sectionCount} onChange={(e)=>setSectionCount(parseInt(e.target.value))}/>
                   </div>

                   <div className="flex flex-col gap-3 pt-3 border-t border-slate-700">
                        <div className="flex justify-between items-center">
                            <span className="text-[10px] font-black text-slate-500 uppercase">Proctors:</span>
                            <div className="flex bg-slate-900 p-1 rounded-lg">
                                <button onClick={()=>setProctorPref('department')} className={`px-3 py-1 text-[9px] font-black rounded-md ${proctorPref === 'department' ? 'bg-blue-600' : ''}`}>DEPT</button>
                                <button onClick={()=>setProctorPref('global')} className={`px-3 py-1 text-[9px] font-black rounded-md ${proctorPref === 'global' ? 'bg-blue-600' : ''}`}>GLOBAL</button>
                            </div>
                        </div>
                        <div className="flex justify-between items-center">
                            <span className="text-[10px] font-black text-slate-500 uppercase">Rooms:</span>
                            <div className="flex bg-slate-900 p-1 rounded-lg">
                                <button onClick={()=>setRoomPref('department')} className={`px-3 py-1 text-[9px] font-black rounded-md ${roomPref === 'department' ? 'bg-amber-600' : ''}`}>PREF</button>
                                <button onClick={()=>setRoomPref('global')} className={`px-3 py-1 text-[9px] font-black rounded-md ${roomPref === 'global' ? 'bg-amber-600' : ''}`}>GLOBAL</button>
                            </div>
                        </div>
                   </div>
                </div>
              </div>
            </div>

            <button onClick={generateSchedule} className="w-full mt-10 bg-blue-600 hover:bg-blue-500 text-white font-black py-5 rounded-2xl shadow-2xl flex justify-center items-center gap-4 text-sm uppercase tracking-[0.2em] transition-all active:scale-95 group">
               <Play size={20} fill="currentColor" className="group-hover:translate-x-1 transition-transform"/> Run {deptCode} Conflict-Free Generator
            </button>
        </div>
      </div>
    </div>
  );
};

export default DepartmentCard;
